package com.yihe.framework.ehr;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.itextpdf.text.pdf.PdfReader;
import com.itextpdf.text.pdf.parser.PdfTextExtractor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import javax.servlet.http.*;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;import java.io.*;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/ocr-templates")
public class OcrTemplateApi {
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();
 @Value("${ehr.storage-root:${EHR_STORAGE_ROOT:D:/update}}") private String storage;
 public OcrTemplateApi(EhrAccess access,EhrRepository db){this.access=access;this.db=db;}
 @ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}
 private String s(Object v){return v==null?"":String.valueOf(v);}private void check(boolean v,String msg){if(!v)throw new EhrException(422,msg);}
 private Path file(EhrActor a){return Paths.get(storage,".ocr-templates",Base64.getUrlEncoder().withoutPadding().encodeToString(digest(bytes(a.scope+":"+a.mode)))+".json");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> dictionary(){List<Map<String,Object>> list=db.all("SELECT field_key code,field_name name,field_category category,definition FROM a_standard_field_dictionary WHERE dictionary_version='2.0.0' ORDER BY source_row");try(InputStream in=getClass().getResourceAsStream("/ehr/ocr-standard-fields.json")){if(in!=null){Map<String,Object> source=json.readValue(in,Map.class);for(Map<String,Object> row:list){Object ref=source.get(s(row.get("code")));if(ref instanceof Map)for(String key:Arrays.asList("name","category","definition")){String value=s(row.get(key));if(value.contains("\uFFFD")||(!value.matches(".*[\u4e00-\u9fff].*")&&s(((Map<?,?>)ref).get(key)).matches(".*[\u4e00-\u9fff].*")))row.put(key,((Map<?,?>)ref).get(key));}}}}catch(IOException ex){throw new EhrException(500,"字段字典显示资源无法读取");}return list;}

 private Map<String,Object> initial(){List<Object> fields=new ArrayList<>();List<Map<String,Object>> dictionary=dictionary();for(Map<String,Object> row:dictionary){String name=s(row.get("name"));if(!name.matches(".*(姓名|性别|年龄|工号|日期|单位|部门|血压|血糖|结论|体检号).*"))continue;int i=fields.size();fields.add(map("id",UUID.randomUUID().toString(),"name",name,"code",row.get("code"),"type",name.contains("日期")?"date":"text","method","keyword","keyword",name,"pattern","","required",false,"x",7,"y",12+(i%10)*7,"w",86,"h",5));if(fields.size()>=18)break;}Set<String> used=new HashSet<>();for(Object f:fields)used.add(s(((Map<?,?>)f).get("code")));for(Map<String,Object> row:dictionary){if(fields.size()>=18)break;if(!used.add(s(row.get("code"))))continue;int i=fields.size();fields.add(map("id",UUID.randomUUID().toString(),"name",row.get("name"),"code",row.get("code"),"type","text","method","keyword","keyword",row.get("name"),"pattern","","required",false,"x",7,"y",12+(i%10)*7,"w",86,"h",5));}Map<String,Object> template=map("id","general","name","通用报告字段模板","kind","体检报告","enabled",true,"description","基于现有标准档案字段字典配置","fields",fields,"rules",map("trim",true),"revision",1,"updatedAt",now());return map("version",0,"templates",Arrays.asList(template),"history",new ArrayList<>(),"tests",new ArrayList<>());}
 @SuppressWarnings("unchecked") private Map<String,Object> read(EhrActor a)throws IOException{Path p=file(a);if(!Files.exists(p))return initial();check(Files.size(p)<=12582912,"模板配置过大");return json.readValue(Files.readAllBytes(p),Map.class);}
 private void write(EhrActor a,Map<String,Object> body)throws IOException{byte[] bytes=json.writeValueAsBytes(body);check(bytes.length<=12582912,"模板配置超过12MB");Path p=file(a);Files.createDirectories(p.getParent());Path t=Files.createTempFile(p.getParent(),"template-",".tmp");try{Files.write(t,bytes);try{Files.move(t,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(t,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(t);}}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v,int max){check(v instanceof List&&((List<?>)v).size()<=max,"模板列表无效或超过限制");List<Map<String,Object>> out=new ArrayList<>();for(Object r:(List<?>)v){check(r instanceof Map,"配置行格式无效");out.add((Map<String,Object>)r);}return out;}
 private void text(Map<String,Object> row,String k,int max,boolean required){String value=s(row.get(k));check(value.length()<=max&&(!required||!value.trim().isEmpty()),"字段 "+k+" 为空或过长");}
 private Pattern pattern(String p){check(p.length()<=160&&!p.matches(".*[+*|].*")&&!p.contains("?")&&!p.matches(".*\\)[{].*")&&!p.matches(".*\\\\[1-9].*"),"正则请使用有界量词，例如 ([0-9.]{1,20})，不支持无界量词、分支或回溯引用");int opens=0,closes=0;for(char c:p.toCharArray()){if(c=='(')opens++;if(c==')')closes++;}check(opens<=1&&closes<=1,"正则最多使用一个捕获组");Matcher bounds=Pattern.compile("\\{([^}]+)\\}").matcher(p);int count=0;while(bounds.find()){check(++count<=3&&bounds.group(1).matches("[0-9]{1,2}(,[0-9]{1,2})?"),"正则量词须有界且不超过三处");for(String n:bounds.group(1).split(","))check(Integer.parseInt(n)<=64,"正则量词最大64");}try{return Pattern.compile(p);}catch(PatternSyntaxException ex){throw new EhrException(422,"正则表达式格式错误");}}
 @GetMapping public synchronized Object get(HttpServletRequest r)throws IOException{Map<String,Object> result=new LinkedHashMap<>(read(access.web(r)));result.put("dictionary",dictionary());return ok(result);}
 @PutMapping public synchronized Object save(HttpServletRequest r,@RequestBody Map<String,Object> b)throws IOException{EhrActor a=access.web(r);Map<String,Object> old=read(a);if(EhrService.num(b.get("version"))!=EhrService.num(old.get("version")))throw new EhrException(409,"模板已被其他人员修改，请刷新后重试");List<Map<String,Object>> templates=rows(b.get("templates"),100),previous=rows(old.get("templates"),100),history=rows(old.get("history"),1000);Set<String> ids=new HashSet<>();for(Map<String,Object> t:templates){text(t,"id",100,true);text(t,"name",150,true);text(t,"description",1000,false);check(ids.add(s(t.get("id"))),"模板ID重复");Set<String> codes=new HashSet<>(),fieldIds=new HashSet<>();for(Map<String,Object> f:rows(t.get("fields"),250)){text(f,"id",100,true);text(f,"name",150,true);text(f,"code",100,true);text(f,"keyword",200,false);check(codes.add(s(f.get("code")))&&fieldIds.add(s(f.get("id"))),"字段编码或ID重复");check(s(f.get("code")).matches("[A-Za-z][A-Za-z0-9_.-]{0,99}"),"字段编码格式错误");check(Arrays.asList("text","number","date").contains(s(f.get("type"))),"字段类型无效");check(Arrays.asList("keyword","regex","table").contains(s(f.get("method"))),"识别方式无效");if("regex".equals(f.get("method"))){text(f,"pattern",160,true);pattern(s(f.get("pattern")));}for(String k:Arrays.asList("x","y","w","h")){Object raw=f.get(k);check(raw instanceof Number,"位置参数须为数值");double n=((Number)raw).doubleValue();check(Double.isFinite(n)&&n>=0&&n<=100,"位置参数须在0至100之间");}check(((Number)f.get("x")).doubleValue()+((Number)f.get("w")).doubleValue()<=100&&((Number)f.get("y")).doubleValue()+((Number)f.get("h")).doubleValue()<=100&&((Number)f.get("w")).doubleValue()>0&&((Number)f.get("h")).doubleValue()>0,"标注区域超出页面或尺寸无效");}
 Map<String,Object> prior=previous.stream().filter(p->s(p.get("id")).equals(s(t.get("id")))).findFirst().orElse(null);boolean changed=prior==null||!json.writeValueAsString(prior).equals(json.writeValueAsString(t));if(changed){if(prior!=null)history.add(map("id",UUID.randomUUID().toString(),"templateId",prior.get("id"),"name",prior.get("name"),"revision",prior.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",prior));t.put("revision",prior==null?1:EhrService.num(prior.get("revision"))+1);t.put("updatedAt",now());}}
 for(Map<String,Object> p:previous)if(!ids.contains(s(p.get("id"))))history.add(map("id",UUID.randomUUID().toString(),"templateId",p.get("id"),"name",p.get("name"),"revision",p.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",p));if(history.size()>120)history=new ArrayList<>(history.subList(history.size()-120,history.size()));Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"templates",templates,"history",history,"tests",old.get("tests"));write(a,next);next.put("dictionary",dictionary());return ok(next);}
 @PostMapping("/test") public synchronized Object test(HttpServletRequest r,@RequestParam String templateId,@RequestParam(defaultValue="") String text,@RequestParam(value="file",required=false) MultipartFile upload)throws IOException{EhrActor a=access.web(r);Map<String,Object> data=read(a),template=rows(data.get("templates"),100).stream().filter(t->s(t.get("id")).equals(templateId)).findFirst().orElseThrow(()->new EhrException(404,"模板不存在"));check(!Boolean.FALSE.equals(template.get("enabled")),"模板已停用");String source="粘贴文本";if(upload!=null&&!upload.isEmpty()){check(upload.getSize()<=10485760,"文件不能超过10MB");String name=s(upload.getOriginalFilename());source=name.length()>150?name.substring(0,150):name;if(name.toLowerCase(Locale.ROOT).endsWith(".txt"))text=new String(upload.getBytes(),StandardCharsets.UTF_8);else if(name.toLowerCase(Locale.ROOT).endsWith(".pdf")){StringBuilder out=new StringBuilder();PdfReader reader=null;try{reader=new PdfReader(upload.getBytes());check(reader.getNumberOfPages()<=20,"测试PDF最多20页");for(int i=1;i<=reader.getNumberOfPages();i++){out.append(PdfTextExtractor.getTextFromPage(reader,i)).append('\n');check(out.length()<=50000,"提取文本过长，请缩小测试文档");}text=out.toString();}catch(EhrException ex){throw ex;}catch(Exception ex){throw new EhrException(422,"PDF无法读取，请检查文件是否加密或损坏");}finally{if(reader!=null)reader.close();}}else throw new EhrException(422,"支持UTF-8文本或含文字层PDF；扫描件请先完成OCR后粘贴识别文字");}
 check(!text.trim().isEmpty(),"未读到文字；扫描件请先完成OCR后粘贴识别文字");check(text.length()<=50000,"测试文本不能超过50000字");List<Object> results=new ArrayList<>();int matched=0;for(Map<String,Object> f:rows(template.get("fields"),250)){String value="",key=s(f.get("keyword"));if(key.isEmpty())key=s(f.get("name"));if("regex".equals(f.get("method"))){Matcher m=pattern(s(f.get("pattern"))).matcher(text);if(m.find())value=m.groupCount()>0?m.group(1):m.group();}else{for(String line:text.split("\\r?\\n")){int at=line.indexOf(key);if(at>=0){value=line.substring(at+key.length()).replaceFirst("^[\\s:：=|]+","").trim();if("table".equals(f.get("method")))value=value.split("[|\\t]",2)[0].trim();break;}}}if(value.length()>2000)value=value.substring(0,2000);boolean valid=!value.isEmpty();if(valid&&"number".equals(f.get("type")))valid=value.matches("[-+]?[0-9]+(\\.[0-9]+)?");if(valid&&"date".equals(f.get("type")))valid=value.matches("[0-9]{4}[-/年][0-9]{1,2}[-/月][0-9]{1,2}日?");if(valid)matched++;results.add(map("code",f.get("code"),"name",f.get("name"),"value",value,"required",f.get("required"),"status",value.isEmpty()?"missing":valid?"matched":"invalid"));}
 List<Map<String,Object>> tests=rows(data.get("tests"),1000);Map<String,Object> log=map("id",UUID.randomUUID().toString(),"templateId",templateId,"templateName",template.get("name"),"revision",template.get("revision"),"source",source,"matched",matched,"total",results.size(),"createdAt",now());tests.add(log);if(tests.size()>200)tests=new ArrayList<>(tests.subList(tests.size()-200,tests.size()));data.put("tests",tests);data.put("version",EhrService.num(data.get("version"))+1);write(a,data);return ok(map("results",results,"record",log,"version",data.get("version")));}
}
